export const SCHEMA_SQL = "-- ===========================================================================\n-- ai-employee-platform :: core schema (portable Postgres 15+)\n--\n-- Portable on purpose: it runs unchanged on Supabase/Postgres and on the\n-- in-process PGlite test harness, so the tests exercise the real SQL rather\n-- than a mock. pgvector is optional — see db/pgvector.sql for the production\n-- upgrade that swaps embedding double precision[] for vector(1536).\n-- ===========================================================================\n\ncreate schema if not exists auth;\n\n-- Supabase exposes the caller's JWT subject as auth.uid(). Every RLS policy\n-- below is written against it, so the same policies work in production and in\n-- tests (the harness sets request.jwt.claim.sub to impersonate a tenant).\ncreate or replace function auth.uid() returns uuid\nlanguage sql stable\nas $$\n  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid\n$$;\n\ngrant usage on schema auth to public;\ngrant execute on function auth.uid() to public;\n\n-- ---------------------------------------------------------------------------\n-- Tenants\n-- ---------------------------------------------------------------------------\ncreate table if not exists profiles (\n  id                  uuid primary key,\n  email               text not null unique,\n  company_name        text,\n  plan                text not null default 'trial'\n                      check (plan in ('trial', 'starter', 'growth', 'scale')),\n  status              text not null default 'trialing'\n                      check (status in ('trialing', 'active', 'past_due', 'canceled')),\n  trial_ends_at       timestamptz not null default (now() + interval '14 days'),\n  seats               integer not null default 1 check (seats between 1 and 500),\n  is_superadmin       boolean not null default false,\n  billing_customer_id text,\n  created_at          timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------------\n-- Encrypted third-party credentials. One row per tenant per provider.\n-- ciphertext is AES-256-GCM, formatted \"v<keyVersion>:<b64 iv>:<b64 ct>:<b64 tag>\".\n-- The vault never stores plaintext and never logs it.\n-- ---------------------------------------------------------------------------\ncreate table if not exists credentials (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references profiles(id) on delete cascade,\n  provider    text not null check (length(provider) between 1 and 64),\n  ciphertext  text not null,\n  key_version text not null,\n  created_at  timestamptz not null default now(),\n  rotated_at  timestamptz,\n  unique (user_id, provider)\n);\n\n-- ---------------------------------------------------------------------------\n-- Deployed AI employees\n-- ---------------------------------------------------------------------------\ncreate table if not exists employees (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references profiles(id) on delete cascade,\n  kind       text not null,\n  name       text not null,\n  status     text not null default 'online'\n             check (status in ('online', 'paused', 'error')),\n  config     jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists employees_user_idx on employees (user_id);\n\n-- ---------------------------------------------------------------------------\n-- Conversation log\n-- ---------------------------------------------------------------------------\ncreate table if not exists messages (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references profiles(id) on delete cascade,\n  employee_id uuid not null references employees(id) on delete cascade,\n  role        text not null check (role in ('user', 'agent', 'system', 'tool')),\n  content     text not null,\n  created_at  timestamptz not null default now()\n);\ncreate index if not exists messages_user_idx on messages (user_id, created_at desc);\n\n-- ---------------------------------------------------------------------------\n-- Knowledge base. embedding is double precision[] in the portable schema and\n-- becomes vector(1536) after db/pgvector.sql. Retrieval uses cosine_similarity\n-- either way, so the query path is identical in tests and production.\n-- ---------------------------------------------------------------------------\ncreate table if not exists documents (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references profiles(id) on delete cascade,\n  title      text not null,\n  content    text not null,\n  embedding  double precision[],\n  created_at timestamptz not null default now()\n);\ncreate index if not exists documents_user_idx on documents (user_id);\n\ncreate or replace function cosine_similarity(a double precision[], b double precision[])\nreturns double precision\nlanguage plpgsql immutable\nas $$\ndeclare\n  dot double precision := 0;\n  na  double precision := 0;\n  nb  double precision := 0;\n  i   integer;\nbegin\n  if a is null or b is null or array_length(a, 1) is distinct from array_length(b, 1) then\n    return null;\n  end if;\n  for i in 1 .. array_length(a, 1) loop\n    dot := dot + (a[i] * b[i]);\n    na  := na + (a[i] * a[i]);\n    nb  := nb + (b[i] * b[i]);\n  end loop;\n  if na = 0 or nb = 0 then\n    return 0;\n  end if;\n  return dot / (sqrt(na) * sqrt(nb));\nend;\n$$;\n\n-- ---------------------------------------------------------------------------\n-- Webhook idempotency. The primary key IS the idempotency key, so a duplicate\n-- delivery cannot create a second row: `insert ... on conflict do nothing`\n-- returns zero rows on replay. payload_sha256 detects key reuse with a\n-- different body, which is a bug or an attack, never a normal retry.\n-- ---------------------------------------------------------------------------\ncreate table if not exists webhook_receipts (\n  idempotency_key text primary key,\n  provider        text not null,\n  event_id        text not null,\n  payload_sha256  text not null,\n  status          text not null default 'claimed'\n                  check (status in ('claimed', 'processed', 'failed')),\n  attempts        integer not null default 0,\n  received_at     timestamptz not null default now(),\n  processed_at    timestamptz\n);\ncreate index if not exists webhook_receipts_event_idx on webhook_receipts (provider, event_id);\n\n-- ---------------------------------------------------------------------------\n-- One row per agent invocation. This is the cost and latency ledger.\n-- ---------------------------------------------------------------------------\ncreate table if not exists workflow_runs (\n  id                uuid primary key default gen_random_uuid(),\n  user_id           uuid not null references profiles(id) on delete cascade,\n  employee_id       uuid references employees(id) on delete set null,\n  trace_id          text not null,\n  status            text not null default 'running'\n                    check (status in ('running', 'succeeded', 'failed', 'dead_letter')),\n  model             text,\n  prompt_tokens     integer,\n  completion_tokens integer,\n  cost_usd          numeric(12, 6),\n  latency_ms        integer,\n  error             text,\n  started_at        timestamptz not null default now(),\n  finished_at       timestamptz\n);\ncreate index if not exists workflow_runs_user_idx on workflow_runs (user_id, started_at desc);\n\n-- ---------------------------------------------------------------------------\n-- Hash-chained audit ledger. entry_hash = sha256(prev_hash || canonical_json).\n-- The application writes it (src/audit/ledger.ts) so the chain is verifiable\n-- independently of the database; audit_log is append-only by policy.\n-- ---------------------------------------------------------------------------\ncreate table if not exists audit_log (\n  seq        bigserial primary key,\n  user_id    uuid,\n  actor      text not null,\n  action     text not null,\n  subject    text,\n  payload    jsonb not null default '{}'::jsonb,\n  prev_hash  text not null,\n  entry_hash text not null,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists audit_log_user_idx on audit_log (user_id, seq desc);\n\n-- ---------------------------------------------------------------------------\n-- Privilege guard: a tenant may edit its own profile fields, but must never be\n-- able to grant itself a paid plan, extra seats, an extended trial, or\n-- superadmin. Only a privileged connection (service role, or a session that\n-- sets app.privileged='on') can change those columns.\n-- ---------------------------------------------------------------------------\ncreate or replace function guard_profile_privileges()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if coalesce(current_setting('app.privileged', true), 'off') = 'on' then\n    return new;\n  end if;\n\n  if new.plan is distinct from old.plan\n     or new.status is distinct from old.status\n     or new.trial_ends_at is distinct from old.trial_ends_at\n     or new.seats is distinct from old.seats\n     or new.is_superadmin is distinct from old.is_superadmin\n     or new.billing_customer_id is distinct from old.billing_customer_id then\n    raise exception 'privilege_escalation_blocked: plan, status, trial_ends_at, seats, is_superadmin and billing_customer_id are service-role only'\n      using errcode = '42501';\n  end if;\n\n  return new;\nend;\n$$;\n\ndrop trigger if exists profiles_privilege_guard on profiles;\ncreate trigger profiles_privilege_guard\n  before update on profiles\n  for each row execute function guard_profile_privileges();\n";

export const ROLES_SQL = "-- ===========================================================================\n-- ai-employee-platform :: local roles\n--\n-- Supabase already provisions these roles. The in-process test harness and the\n-- demo seed them so the exact same policies run locally. This file is NOT\n-- applied to a real Supabase project.\n-- ===========================================================================\n\ndo $$\nbegin\n  if not exists (select 1 from pg_roles where rolname = 'authenticated') then\n    create role authenticated nologin;\n  end if;\n  if not exists (select 1 from pg_roles where rolname = 'anon') then\n    create role anon nologin;\n  end if;\n  if not exists (select 1 from pg_roles where rolname = 'service_role') then\n    create role service_role nologin bypassrls;\n  end if;\nend\n$$;\n\ngrant usage on schema public to authenticated, anon, service_role;\ngrant usage on schema auth to authenticated, anon, service_role;\n\ngrant select, insert, update, delete on all tables in schema public to authenticated;\ngrant select, insert, update, delete on all tables in schema public to service_role;\ngrant usage, select on all sequences in schema public to authenticated, service_role;\ngrant execute on all functions in schema public to authenticated, service_role;\n";

export const POLICIES_SQL = "-- ===========================================================================\n-- ai-employee-platform :: row level security\n--\n-- Tenancy model: every tenant-owned row carries user_id = profiles.id. The\n-- policies below are the ONLY thing standing between tenant A and tenant B,\n-- so they are treated as security-critical code and covered by the adversarial\n-- suite in tests/rls.test.ts.\n--\n-- Roles mirror Supabase:\n--   authenticated — a logged-in tenant, subject to RLS\n--   anon          — no session, must see nothing\n--   service_role  — server-side operations, bypasses RLS by design\n-- ===========================================================================\n\nalter table profiles          enable row level security;\nalter table credentials       enable row level security;\nalter table employees         enable row level security;\nalter table messages          enable row level security;\nalter table documents         enable row level security;\nalter table webhook_receipts  enable row level security;\nalter table workflow_runs     enable row level security;\nalter table audit_log         enable row level security;\n\n-- Force RLS for table owners too; otherwise a owner-role connection silently\n-- ignores every policy and the security model is decorative.\nalter table profiles          force row level security;\nalter table credentials       force row level security;\nalter table employees         force row level security;\nalter table messages          force row level security;\nalter table documents         force row level security;\nalter table webhook_receipts  force row level security;\nalter table workflow_runs     force row level security;\nalter table audit_log         force row level security;\n\n-- --------------------------------------------------------------------------\n-- profiles: read and update your own row. Creation is handled by the signup\n-- trigger on auth.users (service role), so tenants get no INSERT policy.\n-- --------------------------------------------------------------------------\ndrop policy if exists profiles_select_own on profiles;\ncreate policy profiles_select_own on profiles\n  for select to authenticated\n  using (auth.uid() = id);\n\ndrop policy if exists profiles_update_own on profiles;\ncreate policy profiles_update_own on profiles\n  for update to authenticated\n  using (auth.uid() = id)\n  with check (auth.uid() = id);\n\n-- --------------------------------------------------------------------------\n-- credentials: a tenant owns its vault entries and nothing else. No SELECT of\n-- another tenant's ciphertext, and no ability to write a row owned by someone\n-- else (that is what the WITH CHECK clause prevents).\n-- --------------------------------------------------------------------------\ndrop policy if exists credentials_tenant_all on credentials;\ncreate policy credentials_tenant_all on credentials\n  for all to authenticated\n  using (auth.uid() = user_id)\n  with check (auth.uid() = user_id);\n\n-- --------------------------------------------------------------------------\n-- employees\n-- --------------------------------------------------------------------------\ndrop policy if exists employees_tenant_all on employees;\ncreate policy employees_tenant_all on employees\n  for all to authenticated\n  using (auth.uid() = user_id)\n  with check (auth.uid() = user_id);\n\n-- --------------------------------------------------------------------------\n-- messages: readable only inside the tenant.\n-- --------------------------------------------------------------------------\ndrop policy if exists messages_tenant_select on messages;\ncreate policy messages_tenant_select on messages\n  for select to authenticated\n  using (auth.uid() = user_id);\n\n-- Checking user_id alone is not enough: without the EXISTS clause a tenant can\n-- attach a message to another tenant's employee id, which is a cross-tenant\n-- reference even though the row itself looks \"owned\". The reference must be\n-- validated against a row the caller can actually see.\ndrop policy if exists messages_tenant_insert on messages;\ncreate policy messages_tenant_insert on messages\n  for insert to authenticated\n  with check (\n    auth.uid() = user_id\n    and exists (\n      select 1 from employees e\n      where e.id = messages.employee_id\n        and e.user_id = auth.uid()\n    )\n  );\n\n-- --------------------------------------------------------------------------\n-- documents: the RAG corpus. Same isolation rule as everything else.\n-- --------------------------------------------------------------------------\ndrop policy if exists documents_tenant_all on documents;\ncreate policy documents_tenant_all on documents\n  for all to authenticated\n  using (auth.uid() = user_id)\n  with check (auth.uid() = user_id);\n\n-- --------------------------------------------------------------------------\n-- workflow_runs: a tenant can read its own cost/latency rows but cannot forge\n-- or mutate them; only the service role writes them.\n-- --------------------------------------------------------------------------\ndrop policy if exists workflow_runs_tenant_select on workflow_runs;\ncreate policy workflow_runs_tenant_select on workflow_runs\n  for select to authenticated\n  using (auth.uid() = user_id);\n\n-- --------------------------------------------------------------------------\n-- audit_log: append-only and tenant-scoped. There is deliberately no UPDATE or\n-- DELETE policy, so a compromised tenant session cannot rewrite history.\n-- The service role writes entries; the tenant reads its own.\n-- --------------------------------------------------------------------------\ndrop policy if exists audit_log_tenant_select on audit_log;\ncreate policy audit_log_tenant_select on audit_log\n  for select to authenticated\n  using (user_id is null or auth.uid() = user_id);\n\n-- --------------------------------------------------------------------------\n-- webhook_receipts: internal bookkeeping. No tenant-facing policy at all, so\n-- an authenticated session sees zero rows and the service role does all work.\n-- --------------------------------------------------------------------------\n\n-- --------------------------------------------------------------------------\n-- anon: explicitly nothing. Revoking default grant makes the intent explicit\n-- instead of relying on \"no policy happens to deny it\".\n-- --------------------------------------------------------------------------\nrevoke all on all tables in schema public from anon;\n";

export const SEED_SQL = "-- ===========================================================================\n-- ai-employee-platform :: deterministic demo data\n--\n-- Two competing tenants, each with its own employees, documents and audit\n-- history. Used by the test suite as the adversarial fixture (A must never see\n-- B) and by the demo CLI.\n-- ===========================================================================\n\n-- Fixed ids so tests can reason about them without a lookup round trip.\n-- Tenant A = Acme Robotics, tenant B = Globex Logistics.\n\nset app.privileged = 'on';\n\ninsert into profiles (id, email, company_name, plan, status, trial_ends_at, seats)\nvalues\n  ('11111111-1111-4111-8111-111111111111', 'ops@acme.test',   'Acme Robotics',   'growth',  'active',   now() - interval '1 day', 5),\n  ('22222222-2222-4222-8222-222222222222', 'ops@globex.test', 'Globex Logistics', 'starter', 'active',   now() - interval '1 day', 2)\non conflict (id) do nothing;\n\ninsert into employees (id, user_id, kind, name, status)\nvalues\n  ('aaaaaaaa-1111-4111-8111-aaaaaaaaaaaa', '11111111-1111-4111-8111-111111111111', 'support',  'Acme Support Agent',  'online'),\n  ('bbbbbbbb-2222-4222-8222-bbbbbbbbbbbb', '22222222-2222-4222-8222-222222222222', 'sales',    'Globex Lead Agent',   'online')\non conflict (id) do nothing;\n\ninsert into documents (id, user_id, title, content, embedding)\nvalues\n  ('dddddddd-1111-4111-8111-dddddddddddd',\n   '11111111-1111-4111-8111-111111111111',\n   'Acme refund policy',\n   'Refunds are available within 30 days of purchase for unused hardware.',\n   array[0.9, 0.1, 0.0]::double precision[]),\n  ('eeeeeeee-2222-4222-8222-eeeeeeeeeeee',\n   '22222222-2222-4222-8222-222222222222',\n   'Globex freight SLA',\n   'Freight shipments are delivered within 5 business days across EMEA.',\n   array[0.0, 0.9, 0.1]::double precision[])\non conflict (id) do nothing;\n\ninsert into messages (user_id, employee_id, role, content)\nvalues\n  ('11111111-1111-4111-8111-111111111111', 'aaaaaaaa-1111-4111-8111-aaaaaaaaaaaa', 'user',  'Can I still refund a unit bought 20 days ago?'),\n  ('11111111-1111-4111-8111-111111111111', 'aaaaaaaa-1111-4111-8111-aaaaaaaaaaaa', 'agent', 'Yes - 20 days is inside the 30 day window.'),\n  ('22222222-2222-4222-8222-222222222222', 'bbbbbbbb-2222-4222-8222-bbbbbbbbbbbb', 'user',  'What is the EMEA delivery SLA?');\n\nreset app.privileged;\n";

export const OPS_SQL = "-- ===========================================================================\n-- ai-employee-platform :: business operations domain\n--\n-- The core schema models tenancy, credentials, employees and documents. This\n-- file adds the objects an AI employee actually operates on when the job is\n-- \"work the pipeline\": leads, enrichment signals, drafted outreach, approval\n-- decisions, sends, and the run ledger that records what the agent did.\n--\n-- Same rules as the core schema: portable Postgres, every tenant-owned row\n-- carries user_id = profiles.id, and RLS is enabled and forced.\n-- ===========================================================================\n\n-- ---------------------------------------------------------------------------\n-- Leads\n-- ---------------------------------------------------------------------------\ncreate table if not exists leads (\n  id              uuid primary key default gen_random_uuid(),\n  user_id         uuid not null references profiles(id) on delete cascade,\n  company         text not null check (length(company) between 1 and 160),\n  domain          text not null check (domain ~ '^[a-z0-9.-]+\\.[a-z]{2,}$'),\n  contact_name    text not null,\n  contact_role    text not null,\n  contact_email   text not null,\n  source          text not null check (source in ('inbound', 'outbound', 'referral', 'event', 'partner')),\n  stage           text not null default 'new'\n                  check (stage in ('new', 'qualified', 'contacted', 'replied', 'meeting', 'won', 'lost', 'disqualified')),\n  employees       integer check (employees between 1 and 100000),\n  funding_stage   text check (funding_stage in ('bootstrapped', 'seed', 'series_a', 'series_b', 'series_c', 'public')),\n  hq_city         text,\n  last_contact_at timestamptz,\n  replied_at      timestamptz,\n  created_at      timestamptz not null default now(),\n  unique (user_id, domain)\n);\n\ncreate index if not exists leads_user_stage_idx      on leads (user_id, stage);\ncreate index if not exists leads_user_contact_idx    on leads (user_id, last_contact_at desc);\ncreate index if not exists leads_user_source_idx     on leads (user_id, source);\n\n-- ---------------------------------------------------------------------------\n-- Enrichment signals. One row per observed fact, with the weight the scorer\n-- uses. Keeping weight on the row (not in code) means the scoring model can be\n-- audited per lead and re-tuned without a deploy.\n-- ---------------------------------------------------------------------------\ncreate table if not exists lead_signals (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references profiles(id) on delete cascade,\n  lead_id     uuid not null references leads(id) on delete cascade,\n  kind        text not null check (kind in ('hiring', 'funding', 'tech', 'traffic', 'intent', 'friction')),\n  value       text not null check (length(value) between 1 and 240),\n  weight      numeric(4, 3) not null check (weight between -1 and 1),\n  observed_at timestamptz not null default now()\n);\n\ncreate index if not exists lead_signals_lead_idx on lead_signals (lead_id);\n\n-- ---------------------------------------------------------------------------\n-- Drafts. content_hash is unique per tenant, which is what makes \"draft the\n-- same lead twice\" idempotent instead of producing duplicate outreach.\n-- ---------------------------------------------------------------------------\ncreate table if not exists drafts (\n  id                 uuid primary key default gen_random_uuid(),\n  user_id            uuid not null references profiles(id) on delete cascade,\n  lead_id            uuid not null references leads(id) on delete cascade,\n  subject            text not null check (length(subject) between 1 and 200),\n  body               text not null check (length(body) between 1 and 4000),\n  status             text not null default 'pending'\n                     check (status in ('pending', 'approved', 'rejected', 'sent', 'failed')),\n  content_hash       text not null check (content_hash ~ '^[0-9a-f]{64}$'),\n  writer             text not null,\n  prompt_tokens      integer not null default 0 check (prompt_tokens >= 0),\n  completion_tokens  integer not null default 0 check (completion_tokens >= 0),\n  cost_usd           numeric(10, 6) not null default 0 check (cost_usd >= 0),\n  created_at         timestamptz not null default now(),\n  unique (user_id, content_hash)\n);\n\ncreate index if not exists drafts_user_status_idx on drafts (user_id, status, created_at desc);\ncreate index if not exists drafts_lead_idx        on drafts (lead_id);\n\n-- ---------------------------------------------------------------------------\n-- Approval decisions. draft_id is unique: a draft is decided exactly once, so\n-- a retried approval cannot flip a rejection into an approval.\n-- ---------------------------------------------------------------------------\ncreate table if not exists approvals (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references profiles(id) on delete cascade,\n  draft_id   uuid not null unique references drafts(id) on delete cascade,\n  -- Monotonic per tenant. The chain has to be ordered by something that is\n  -- unique, otherwise two decisions in the same millisecond can verify in a\n  -- different order than they were written.\n  seq        integer not null check (seq >= 1),\n  decision   text not null check (decision in ('approved', 'rejected')),\n  actor      text not null,\n  note       text,\n  decided_at timestamptz not null default now(),\n  entry_hash text not null check (entry_hash ~ '^[0-9a-f]{64}$'),\n  unique (user_id, seq)\n);\n\ncreate index if not exists approvals_user_idx on approvals (user_id, seq desc);\n\n-- ---------------------------------------------------------------------------\n-- Sends. One row per draft at most; the provider call is claimed before it is\n-- made, so a retry after a timeout cannot double-send.\n-- ---------------------------------------------------------------------------\ncreate table if not exists sends (\n  id                  uuid primary key default gen_random_uuid(),\n  user_id             uuid not null references profiles(id) on delete cascade,\n  draft_id            uuid not null unique references drafts(id) on delete cascade,\n  provider            text not null,\n  provider_message_id text,\n  status              text not null check (status in ('sending', 'sent', 'dry_run', 'failed')),\n  attempts            integer not null default 1 check (attempts >= 1),\n  created_at          timestamptz not null default now(),\n  sent_at             timestamptz\n);\n\ncreate index if not exists sends_user_idx on sends (user_id, created_at desc);\n\n-- ---------------------------------------------------------------------------\n-- Run ledger. One row per agent invocation, one row per step, so the console\n-- can show what happened without parsing logs.\n-- ---------------------------------------------------------------------------\ncreate table if not exists ops_runs (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references profiles(id) on delete cascade,\n  goal        text not null check (length(goal) between 1 and 500),\n  status      text not null default 'running'\n              check (status in ('running', 'awaiting_approval', 'completed', 'failed')),\n  leads_seen  integer not null default 0,\n  drafts_made integer not null default 0,\n  tokens      integer not null default 0,\n  cost_usd    numeric(10, 6) not null default 0,\n  started_at  timestamptz not null default now(),\n  finished_at timestamptz\n);\n\ncreate index if not exists ops_runs_user_idx on ops_runs (user_id, started_at desc);\n\ncreate table if not exists ops_run_steps (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references profiles(id) on delete cascade,\n  run_id     uuid not null references ops_runs(id) on delete cascade,\n  seq        integer not null check (seq >= 0),\n  name       text not null,\n  status     text not null check (status in ('ok', 'retried', 'failed')),\n  attempts   integer not null default 1 check (attempts >= 1),\n  latency_ms integer not null default 0 check (latency_ms >= 0),\n  detail     jsonb not null default '{}'::jsonb,\n  error      text,\n  unique (run_id, seq)\n);\n\ncreate index if not exists ops_run_steps_run_idx on ops_run_steps (run_id, seq);\n\n-- ---------------------------------------------------------------------------\n-- Read model for the console. security_invoker makes the view obey the\n-- caller's RLS instead of the view owner's, which is the difference between a\n-- dashboard and a data leak.\n-- ---------------------------------------------------------------------------\ncreate or replace view lead_pipeline\nwith (security_invoker = true) as\nselect\n  l.user_id,\n  count(*)                                                        as total,\n  count(*) filter (where l.stage = 'qualified')                    as qualified,\n  count(*) filter (where l.stage = 'contacted')                    as contacted,\n  count(*) filter (where l.stage = 'replied')                      as replied,\n  count(*) filter (where l.stage = 'meeting')                      as meeting,\n  count(*) filter (where l.stage = 'won')                          as won,\n  count(*) filter (where l.replied_at is not null)                 as ever_replied,\n  coalesce(sum(l.employees), 0)                                    as employees_reached\nfrom leads l\ngroup by l.user_id;\n\n-- ---------------------------------------------------------------------------\n-- RLS\n-- ---------------------------------------------------------------------------\nalter table leads         enable row level security;\nalter table lead_signals  enable row level security;\nalter table drafts        enable row level security;\nalter table approvals     enable row level security;\nalter table sends         enable row level security;\nalter table ops_runs      enable row level security;\nalter table ops_run_steps enable row level security;\n\nalter table leads         force row level security;\nalter table lead_signals  force row level security;\nalter table drafts        force row level security;\nalter table approvals     force row level security;\nalter table sends         force row level security;\nalter table ops_runs      force row level security;\nalter table ops_run_steps force row level security;\n\ndrop policy if exists leads_rw on leads;\ncreate policy leads_rw on leads\n  for all to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\ndrop policy if exists lead_signals_rw on lead_signals;\ncreate policy lead_signals_rw on lead_signals\n  for all to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\ndrop policy if exists drafts_rw on drafts;\ncreate policy drafts_rw on drafts\n  for all to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\ndrop policy if exists approvals_rw on approvals;\ncreate policy approvals_rw on approvals\n  for all to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\ndrop policy if exists sends_rw on sends;\ncreate policy sends_rw on sends\n  for all to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\ndrop policy if exists ops_runs_rw on ops_runs;\ncreate policy ops_runs_rw on ops_runs\n  for all to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\ndrop policy if exists ops_run_steps_rw on ops_run_steps;\ncreate policy ops_run_steps_rw on ops_run_steps\n  for all to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\n-- Read-only access for anon is intentionally absent: a public visitor must see\n-- nothing. The console authenticates as the seeded tenant.\n\n-- ---------------------------------------------------------------------------\n-- Grants\n--\n-- db/roles.sql runs before this file, so its `grant ... on all tables` does not\n-- cover the objects created above. Without these, `authenticated` is denied at\n-- the grant level and RLS never even runs.\n-- ---------------------------------------------------------------------------\ngrant select, insert, update, delete\n  on leads, lead_signals, drafts, approvals, sends, ops_runs, ops_run_steps\n  to authenticated, service_role;\n\ngrant select on lead_pipeline to authenticated, service_role;\n";

export const OPS_SEED_SQL = "-- ===========================================================================\n-- ai-employee-platform :: deterministic operations fixture\n--\n-- 140 leads for tenant A (Acme Robotics), generated from modulo arithmetic so\n-- every run of the demo sees the same pipeline. No random(), no now() drift\n-- beyond the relative timestamps.\n-- ===========================================================================\n\nset app.privileged = 'on';\n\ninsert into leads (user_id, company, domain, contact_name, contact_role, contact_email, source, stage,\n                   employees, funding_stage, hq_city, last_contact_at, replied_at, created_at)\nselect\n  '11111111-1111-4111-8111-111111111111'::uuid,\n  (array['Kestrel','Lumen','Northwind','Saffron','Verdant','Cobalt','Meridian','Bluebird','Anvil','Trellis','Harbor','Quarry','Summit','Onyx','Willow','Basalt','Indigo','Beacon','Cedar','Fathom'])[1 + (i % 20)]\n    || ' ' ||\n  (array['HR','Payroll','People','Workforce','Talent'])[1 + (i % 5)]\n    || ' ' || (1 + i / 20)::text,\n  'c' || i::text || '.example',\n  (array['Aarav','Diya','Kabir','Meera','Rohan','Ishita','Advait','Nisha','Vikram','Ananya','Dev','Priya'])[1 + (i % 12)]\n    || ' ' ||\n  (array['Shah','Iyer','Patel','Rao','Mehta','Nair','Singh','Kulkarni','Desai'])[1 + (i % 9)],\n  (array['Head of People','VP Engineering','Founder','HR Ops Lead','CTO','People Partner'])[1 + (i % 6)],\n  'lead' || i::text || '@c' || i::text || '.example',\n  (array['inbound','outbound','referral','event','partner'])[1 + (i % 5)],\n  case\n    when i % 100 < 10 then 'new'\n    when i % 100 < 35 then 'qualified'\n    when i % 100 < 60 then 'contacted'\n    when i % 100 < 68 then 'replied'\n    when i % 100 < 74 then 'meeting'\n    when i % 100 < 80 then 'won'\n    when i % 100 < 90 then 'lost'\n    else 'disqualified'\n  end,\n  (array[30, 55, 80, 120, 200, 350, 600, 900, 1500, 2500])[1 + (i % 10)],\n  (array['bootstrapped','seed','series_a','series_b','series_c','public'])[1 + (i % 6)],\n  (array['Bengaluru','Pune','Hyderabad','Gurugram','Mumbai','Ahmedabad','Chennai','Noida'])[1 + (i % 8)],\n  case\n    when i % 100 < 10 then null\n    when i % 100 < 35 then now() - (make_interval(days => 8 + (i % 25)))\n    when i % 100 < 60 then now() - (make_interval(days => 3 + (i % 40)))\n    else now() - (make_interval(days => 2 + (i % 10)))\n  end,\n  case\n    when i % 100 >= 60 and i % 100 < 80 then now() - (make_interval(days => 1 + (i % 8)))\n    else null\n  end,\n  now() - (make_interval(days => 5 + (i % 120)))\nfrom generate_series(1, 140) as g(i);\n\n-- Enrichment signals: every third lead carries one, and every ninth carries a\n-- friction note. The weights are what the scorer uses; changing them here\n-- changes the ranking without touching code.\ninsert into lead_signals (user_id, lead_id, kind, value, weight)\nselect l.user_id, l.id, s.kind, s.value, s.weight\nfrom leads l\njoin generate_series(1, 140) as g(i) on l.domain = 'c' || i::text || '.example'\njoin (values\n  (0, 'intent',  'visited the pricing page three times in 14 days', 0.900::numeric),\n  (1, 'hiring',  'posted three people-ops roles this week',        0.700::numeric),\n  (2, 'funding', 'closed a Series B in October 2026',              0.800::numeric),\n  (3, 'tech',    'runs HubSpot and Postgres, inside the integration path', 0.500::numeric)\n) as s(mod, kind, value, weight) on (i % 4) = s.mod\nwhere l.user_id = '11111111-1111-4111-8111-111111111111'::uuid\n  and i % 3 = 0;\n\ninsert into lead_signals (user_id, lead_id, kind, value, weight)\nselect l.user_id, l.id, 'friction', 'public review mentions a four-day support queue', -0.400::numeric\nfrom leads l\njoin generate_series(1, 140) as g(i) on l.domain = 'c' || i::text || '.example'\nwhere l.user_id = '11111111-1111-4111-8111-111111111111'::uuid\n  and i % 9 = 0;\n\nreset app.privileged;\n";
